#!/usr/bin/env python3
"""Pack pre-reviewed official Bambu PLA Basic Yellow identities for offline testing."""
import base64, json, pathlib
root=pathlib.Path(__file__).resolve().parents[1]
assets=root/'app/src/main/assets/starter'
D={
 'SUNLU_PLA_YELLOW_0524A124.bin':'''''',
 'SUNLU_PLA_SUNFLOWER_ALTERNATIVE_0625AFE6.bin':''''''
}
for filename,blob in D.items():
 data=base64.b64decode(blob)
 assert len(data)==1024,(filename,len(data))
 uid=filename.rsplit('_',1)[1].removesuffix('.bin')
 assert data[:4].hex().upper()==uid,(filename,data[:4])
 bcc=0
 for b in data[:4]:bcc ^= b
 assert bcc==data[4]
 (assets/filename).write_bytes(data)
print('Wrote',len(D),'signed Bambu tag dumps')
indexpath=assets/'index.json';a=json.loads(indexpath.read_text())
entry=[
{"filename":"SUNLU_PLA_YELLOW_0524A124.bin","alias":"SUNLU PLA Yellow","bambu":"Bambu PLA Basic Yellow","color":"#F4EE2A","uid":"0524A124","note":"Closest standard yellow. Third-party material profile remains separate."},
{"filename":"SUNLU_PLA_SUNFLOWER_ALTERNATIVE_0625AFE6.bin","alias":"SUNLU PLA Yellow — golden option","bambu":"Bambu PLA Basic Sunflower Yellow","color":"#FEC600","uid":"0625AFE6","note":"Alternative if your physical yellow leans golden/orange."}
]
a=[x for x in a if not x['filename'].startswith(('SUNLU_PLA_YELLOW_','SUNLU_PLA_SUNFLOWER_ALTERNATIVE_'))]
a=entry+a
indexpath.write_text(json.dumps(a,indent=2)+'\n')
